create policy topic_assignment on post_topics for insert to authenticated with check(owns_post(post_id));
create or replace function index_post() returns trigger language plpgsql security definer set search_path=public as $$declare tag text;begin
 for tag in select lower(m[1]) from regexp_matches(new.body,'#([[:alnum:]_]+)','g')as m loop insert into hashtags(name)values(tag)on conflict do nothing;insert into post_hashtags(post_id,hashtag_id)select new.id,id from hashtags where name=tag on conflict do nothing;insert into post_topics(post_id,topic_id)select new.id,id from topics where lower(name)=tag on conflict do nothing;end loop;return new;end $$;
create function get_list_feed(chosen uuid,before_time timestamptz default null,before_id uuid default null)returns setof posts language sql stable security invoker set search_path=public as $$select p.* from posts p join list_members m on m.profile_id=p.author_id join lists l on l.id=m.list_id where l.id=chosen and l.owner_id=auth.uid()and p.reply_to is null and(before_time is null or(p.created_at,p.id)<(before_time,before_id))and not exists(select 1 from mutes mu where mu.owner_id=auth.uid()and(mu.account_id=p.author_id or mu.word is not null and strpos(lower(p.body),lower(mu.word))>0))order by p.created_at desc,p.id desc limit 25$$;
